<?php session_start();require 'config/database.php';require 'includes/csrf.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$s=$pdo->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username'])]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['name']=$u['full_name'];header('Location: dashboard.php');exit;}$error='Invalid username or password';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"><title>Login</title></head><body><div class="login"><div class="container"><div class="row justify-content-center"><div class="col-md-5 col-lg-4"><div class="box"><h2 class="text-center fw-bold">CFMS</h2><p class="text-center text-muted">Administrator Login</p><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><form method="post"><input type="hidden" name="token" value="<?=token()?>"><input class="form-control mb-3" name="username" placeholder="Username" required><input type="password" class="form-control mb-3" name="password" placeholder="Password" required><button class="btn btn-primary w-100">Login</button></form><small class="d-block text-center mt-3">admin / Admin@123</small></div></div></div></div></div></body></html>